steps.script:
for i in 12:
	if TutorialManager.current_step_id() == 'wagon_mode':
		break
	TutorialManager.skip_step()
return TutorialManager.current_step_id() == 'wagon_mode'

for il in tree.current_scene.find_children('*', 'ItemList', true, false):
	if not il.is_visible_in_tree():
		continue
	for i in il.item_count:
		if il.get_item_text(i).begins_with('Battlewagon'):
			var r = il.get_item_rect(i)
			TouchInputAdapter.inject_tap(il.get_global_transform_with_canvas() * (r.position + r.size * 0.5))
			return true
return false

var p = TouchInputAdapter.get_meta('w')
for k in range(1, 13):
	TouchInputAdapter.inject_drag(0, p + Vector2(0, 2 * k))
return true

var st = TutorialManager.current_lesson.steps[TutorialManager.current_step_index]
var body = TutorialScript.render_text(TutorialScript.body_for_device(st, false), false)
return TutorialManager.current_step_id() == 'wagon_turn' and body.contains('finger') and body.contains('[⟳]')

var p = TouchInputAdapter.get_meta('w')
for k in range(1, 6):
	TouchInputAdapter.inject_drag(0, p + Vector2(4 * k, 0))
return true

var b = TouchInputAdapter.toolbar_button_center('Touch_RotR')
TouchInputAdapter.inject_touch(1, b, true)
return true

var b = TouchInputAdapter.toolbar_button_center('Touch_RotR')
TouchInputAdapter.inject_touch(1, b, false)
return true

var b = TouchInputAdapter.toolbar_button_center('Touch_RotR')
TouchInputAdapter.inject_touch(1, b, true)
return true

var b = TouchInputAdapter.toolbar_button_center('Touch_RotR')
TouchInputAdapter.inject_touch(1, b, false)
return true
